#!/system/bin/sh
# libMEOW Termux installer - extracts libMEOW.so, inject, libMEOW.sh
set -e
DIR="${1:-$HOME/libMEOW}"
mkdir -p "$DIR"
B64=''
echo "$B64" | base64 -d | tar -xz -C "$DIR"
chmod +x "$DIR/libMEOW.sh" "$DIR/inject" "$DIR/libMEOW.so" 2>/dev/null || true
echo "[+] Extracted to $DIR"
echo "[*] Jalankan: sh $DIR/libMEOW.sh com.dts.freefireth"
